def write_try_task_config(comm_src_dir: Path) -> Path:
    try_task_config_file = comm_src_dir / "try_task_config.json"
    try_task_config = {
        "tasks": [
            "build-linux64/opt",
            "build-macosx64/opt",
            "build-win64/opt",
        ]
    }
    with open(try_task_config_file, "w") as try_fp:
        json.dump(try_task_config, try_fp, indent=2)
    return try_task_config_file

def run_try_cc():
    os.chdir(COMM_PATH)
    log("Submitting try-comm-central build.")
    try_task_config = write_try_task_config(COMM_PATH)
    run_cmd([HG, "add", try_task_config.name])
    if OPERATING_MODE == "prod":
        run_cmd([HG, "push-to-try", "-s", "try-cc", "-m", "Automation: Rust build check"])
    else:
        log("Skipping submit to try-comm-central in dev mode...")
